import streamlit as st
import json
import os

# --- CONFIGURATION ---
st.set_page_config(page_title="Surprise!", layout="wide", initial_sidebar_state="collapsed")
STATE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "state.json")

# --- EMBEDDED SOUND EFFECTS (base64-encoded .wav, no external files needed) ---
# Auto-generated base64 audio constants

DIVIDE_WAV_B64 = ""

SUSPENSE_WAV_B64 = ""

CELEBRATION_WAV_B64 = ""

# --- DEFAULT STATE ---
def init_state():
    if not os.path.exists(STATE_FILE):
        with open(STATE_FILE, "w") as f:
            json.dump({
                "number": 80,
                # stages: division -> kbc_question -> options -> locked -> winner
                "stage": "division",
                "seq": 0,  # increments on every admin action so the user page knows something changed
            }, f)

def read_state():
    try:
        with open(STATE_FILE, "r") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        default = {"number": 80, "stage": "division", "seq": 0}
        write_state_raw(default)
        return default

def write_state_raw(state):
    with open(STATE_FILE, "w") as f:
        json.dump(state, f)

def write_state(state):
    state["seq"] = state.get("seq", 0) + 1
    write_state_raw(state)

init_state()
state = read_state()

# --- ROUTING (modern query params API) ---
role = st.query_params.get("role", "user")

# ==========================================
#               ADMIN PANEL
# ==========================================
if role == "admin":
    st.title("⚙️ Admin Control Panel")
    st.caption("Keep this tab private. Share the normal link (without ?role=admin) with everyone else.")
    st.write(f"**Current Number:** {state['number']}")
    st.write(f"**Current Stage:** {state['stage']}")

    st.divider()
    st.subheader("1️⃣ Division Phase")
    dcol1, dcol2 = st.columns(2)
    with dcol1:
        if st.button("➗ Divide by 2", use_container_width=True, type="primary"):
            if state["number"] > 5:
                state["number"] = int(state["number"] / 2)
                state["stage"] = "division"
                write_state(state)
                st.rerun()
            else:
                st.warning("Number is already at 5 — time to move to the KBC round!")
    with dcol2:
        st.write(f"Next value: **{max(5, int(state['number'] / 2)) if state['number'] > 5 else 5}**")

    st.divider()
    st.subheader("2️⃣ KBC Quiz Phase")
    st.caption("Do these in order: Question → Options → Lock → Winner")
    kcol1, kcol2, kcol3, kcol4 = st.columns(4)
    with kcol1:
        if st.button("🎙️ Ask Question", use_container_width=True):
            state["stage"] = "kbc_question"
            write_state(state)
            st.rerun()
    with kcol2:
        if st.button("🔤 Show Options", use_container_width=True):
            state["stage"] = "options"
            write_state(state)
            st.rerun()
    with kcol3:
        if st.button("🔒 Lock Answer", use_container_width=True):
            state["stage"] = "locked"
            write_state(state)
            st.rerun()
    with kcol4:
        if st.button("🏆 Reveal Winner", use_container_width=True, type="primary"):
            state["stage"] = "winner"
            write_state(state)
            st.rerun()

    st.divider()
    if st.button("🔄 Reset Everything"):
        write_state({"number": 80, "stage": "division", "seq": state.get("seq", 0)})
        st.rerun()

    st.divider()
    st.info("Open the normal (non-admin) link on the TV/laptop screen your family will watch, then control everything from here on your phone.")

